void fidelityRackTests(){
    using M=Metropolix;auto m=std::unique_ptr<M>(new M);auto* q=dynamic_cast<ModVoltageQuantity*>(m->getParamQuantity(M::modParam(0,M::MOD_VALUE)));
    require(q,"MOD voltage uses destination-aware native quantity");
    m->params[M::modParam(0,M::MOD_DESTINATION)].setValue(metro::ModPitchPre);q->setDisplayValue(12);require(q->getValue()==1 && q->getDisplayValueString()=="+12" && q->getUnit()==" st","native semitone entry maps exactly to 1 V pitch modulation");
    m->params[M::modParam(0,M::MOD_DESTINATION)].setValue(metro::ModTempo);q->setDisplayValue(80);require(q->getValue()==1 && q->getDisplayValue()==80 && q->getUnit()==" BPM","BPM entry/display uses implemented tempo gain");
    m->params[M::modParam(0,M::MOD_DESTINATION)].setValue(metro::ModProbability);q->setDisplayValue(20);require(q->getValue()==1 && q->getDisplayValue()==20,"probability entry displays percentage point offset");
    m->params[M::modParam(0,M::MOD_DESTINATION)].setValue(metro::ModOctave);q->setValue(-1.9f);require(q->getDisplayValue()==-1,"octave readout truncates exactly like engine");
    m->params[M::modParam(0,M::MOD_DESTINATION)].setValue(metro::ModUserScale);q->setValue(.9f);require(q->getDisplayValue()==0,"user scale readout follows whole volt threshold");
    m->params[M::modParam(0,M::MOD_DESTINATION)].setValue(metro::ModRoot);q->setValue(5);require(q->getDisplayValue()==12,"root readout honors engine one octave limit");
    m->params[M::modParam(0,M::MOD_DESTINATION)].setValue(metro::ModNone);q->setDisplayValue(-2.75f);require(q->getValue()==-2.75f && q->getDisplayValueString()=="-2.75" && q->getUnit()==" V","unassigned MOD still edits volts");
    m->params[M::modParam(0,M::MOD_TYPE)].setValue(metro::ModUnipolar);require(q->getDisplayValue()==0 && m->effectiveModVoltage(0,-2.75f)==0,"positive MOD display hides dormant negative setting");
    m->params[M::modParam(0,M::MOD_DESTINATION)].setValue(metro::ModMute);m->params[M::modParam(0,M::MOD_TYPE)].setValue(0);q->setValue(2);require(q->getDisplayValueString()=="On" && q->getUnit().empty() && m->effectiveModVoltage(0,2)==5,"gate destination readout uses effective On state");
    auto* type=m->getParamQuantity(M::CV_TYPE_1);m->params[M::outputTrackParam(0,M::VELOCITY_SOURCE)].setValue(3);require(type->getDisplayValueString()=="Unipolar + (Velocity CV)" && m->integer(M::CV_TYPE_1)==0,"native CV type tooltip explains forced positive range without mutating saved choice");m->params[M::outputTrackParam(0,M::VELOCITY_SOURCE)].setValue(0);require(type->getDisplayValueString()=="Bipolar ±","removing velocity CV restores original type display");
    auto* driver=new MidiTestDriver;midi::addDriver(24027,driver);m->midiOutput.setDriverId(24027);m->midiOutput.setDeviceId(0);m->params[M::RUN].setValue(0);m->params[M::modParam(0,M::MOD_VALUE)].setValue(0);
    Module::ProcessArgs args{};args.sampleRate=48000;args.sampleTime=1.f/48000;auto frames=[&](int count){for(int n=0;n<count;++n){m->process(args);++args.frame;}};frames(64);driver->output.messages.clear();m->params[M::modParam(0,M::MOD_VALUE)].setValue(2);frames(64);
    auto cc=[&](int value){for(auto& message:driver->output.messages)if(message.bytes.size()==3 && message.bytes[0]==0xb0 && message.bytes[1]==20 && message.bytes[2]==value)return true;return false;};require(cc(127),"stopped MIDI gate learn emits effective high CC127");driver->output.messages.clear();m->params[M::modParam(0,M::MOD_VALUE)].setValue(0);frames(64);require(cc(0),"stopped MIDI gate learn emits CC0 rather than bipolar center");
    for(int stage=0;stage<8;++stage)m->params[M::modParam(0,M::MOD_VALUE+stage)].setValue(2);m->params[M::RUN].setValue(1);driver->output.messages.clear();frames(128);require(cc(127),"running gate destination sends positive CC127");for(int stage=0;stage<8;++stage)m->params[M::modParam(0,M::MOD_VALUE+stage)].setValue(0);driver->output.messages.clear();frames(128);require(cc(0),"running low gate sends CC0");
    for(int i=0;i<10;++i)m->panelPickup[i].recall(m->params[M::panelParam(i)].getValue(),i<8?.8f:.5f);
    frames(32);auto serial=m->sequencer.resetSerial;auto tick=m->sequencer.masterTick;int stage=m->sequencer.tracks[0].stage,pulse=m->sequencer.tracks[0].pulse;
    M::PresetCommand sync;sync.kind=M::PresetCommand::PanelEdit;sync.pickupMask=1023;sync.physical=m->physicalControls();sync.pickup=m->panelPickup;for(auto& pickup:sync.pickup)pickup.active=false;m->presetCommands.push(sync);frames(32);
    require(!m->pickupActiveMask.load() && m->sequencer.resetSerial==serial && m->sequencer.masterTick==tick && m->sequencer.tracks[0].stage==stage && m->sequencer.tracks[0].pulse==pulse,"ten-control panel sync leaves running clock and sequence position intact");
    std::cout<<"PASS: native MOD units/entry, effective CV type, gate MIDI readout and panel sync timing\n";
}
